    select array(select a.code || '|' || coalesce(l.customer_id::text, '') || '|' || l.amount_cents::text
                   from public.ledger_lines l join public.accounts a on a.id = l.account_id
                   join public.journal_entries je on je.id = l.entry_id where je.transaction_id = v_tx order by 1) into v_actual;
    report := report || case when v_actual = v_expected then 'PASS' else 'FAIL (got ' || array_to_string(v_actual, ' ; ') || ')' end || ': opening balances (counted by the owner)' || E'\n';
  exception when others then
    report := report || 'FAIL (error: ' || sqlerrm || '): opening balances (counted by the owner)' || E'\n';
  end;

